{"language":"python","code":"html_content = """<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>ARTIFACT: Museum Night — Warsaw, 18 October 2026</title>
  <meta name="description" content="An intimate after-hours journey through hidden collections, ambient soundscapes, curated talks, and midnight exhibitions at The Old Gallery, Warsaw.">
  <meta property="og:title" content="ARTIFACT: Museum Night — Warsaw, 18 October 2026">
  <meta property="og:description" content="Experience luxury museum after dark. Velvet darkness, golden spotlights, rare collections, and immersive live performances.">
  <meta property="og:image" content="https://source.unsplash.com/featured/2400x1400?museum,night">
  <meta property="og:type" content="website">

  <!-- Inline SVG Favicon -->
  <link rel="icon" href="data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><rect width='100' height='100' rx='20' fill='%23070506'/><circle cx='50' cy='50' r='30' stroke='%23d6ad60' stroke-width='4' fill='none'/><polygon points='50,28 64,68 36,68' fill='%23d6ad60'/></svg>" type="image/svg+xml">

  <style>
    :root {
      --bg-dark: #070506;
      --velvet: #1a0710;
      --burgundy: #3a0f1d;
      --midnight: #07111f;
      --gold: #d6ad60;
      --gold-soft: #f3d79b;
      --gold-glow: rgba(214, 173, 96, 0.4);
      --ivory: #f8efe2;
      --muted: #b9a999;
      --panel-bg: rgba(255, 244, 220, 0.04);
      --panel-bg-hover: rgba(255, 244, 220, 0.08);
      --panel-border: rgba(214, 173, 96, 0.28);
      --panel-border-bright: rgba(243, 215, 155, 0.6);
      --font-headline: "Georgia", "Times New Roman", serif;
      --font-body: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
      --transition: all 0.35s cubic-bezier(0.25, 1, 0.5, 1);
    }

    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    html {
      scroll-behavior: smooth;
      font-size: 16px;
      background-color: var(--bg-dark);
      color: var(--ivory);
      font-family: var(--font-body);
    }

    body {
      background-color: var(--bg-dark);
      color: var(--ivory);
      line-height: 1.6;
      position: relative;
      overflow-x: hidden;
      min-height: 100vh;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    /* CSS-only Subtle Grain / Noise Overlay */
    body::before {
      content: "";
      position: fixed;
      top: 0;
      left: 0;
      width: 100vw;
      height: 100vh;
      pointer-events: none;
      z-index: 999;
      opacity: 0.035;
      background-image: radial-gradient(#d6ad60 1px, transparent 0), radial-gradient(#ffffff 1px, transparent 0);
      background-size: 4px 4px, 6px 6px;
      background-position: 0 0, 2px 2px;
    }

    /* Soft ambient background spotlight blooms */
    .ambient-bloom {
      position: fixed;
      pointer-events: none;
      z-index: 0;
      border-radius: 50%;
      filter: blur(140px);
      opacity: 0.18;
    }
    .bloom-1 {
      width: 600px;
      height: 600px;
      background: var(--burgundy);
      top: 10%;
      right: -100px;
    }
    .bloom-2 {
      width: 700px;
      height: 700px;
      background: var(--midnight);
      top: 45%;
      left: -200px;
    }
    .bloom-3 {
      width: 500px;
      height: 500px;
      background: var(--velvet);
      bottom: 5%;
      right: 10%;
    }

    /* Typography */
    h1, h2, h3, h4, .serif-font {
      font-family: var(--font-headline);
      font-weight: 400;
      letter-spacing: -0.01em;
      color: var(--ivory);
    }

    p {
      color: var(--muted);
      font-size: 1.05rem;
    }

    a {
      color: inherit;
      text-decoration: none;
      transition: var(--transition);
    }

    /* Thin gold divider */
    .gold-divider {
      height: 1px;
      background: linear-gradient(90deg, transparent, var(--panel-border), transparent);
      width: 100%;
      margin: 4rem 0;
    }

    .container {
      max-width: 1240px;
      margin: 0 auto;
      padding: 0 2rem;
      position: relative;
      z-index: 1;
    }

    /* Buttons */
    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      padding: 0.85rem 1.85rem;
      font-size: 0.95rem;
      font-weight: 500;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      cursor: pointer;
      border: 1px solid var(--gold);
      background: transparent;
      color: var(--gold-soft);
      position: relative;
      overflow: hidden;
      transition: var(--transition);
      border-radius: 2px;
      outline: none;
    }
    .btn::after {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(135deg, rgba(214,173,96,0.18), transparent);
      opacity: 0;
      transition: var(--transition);
    }
    .btn:hover {
      color: #070506;
      background: var(--gold);
      box-shadow: 0 0 25px rgba(214, 173, 96, 0.4);
      transform: translateY(-2px);
    }
    .btn:hover::after {
      opacity: 1;
    }
    .btn-solid {
      background: var(--gold);
      color: #070506;
      font-weight: 600;
    }
    .btn-solid:hover {
      background: var(--gold-soft);
      color: #070506;
      box-shadow: 0 0 30px rgba(243, 215, 155, 0.5);
    }
    .btn-ghost {
      border-color: rgba(255, 255, 255, 0.2);
      color: var(--ivory);
    }
    .btn-ghost:hover {
      border-color: var(--gold);
      color: var(--gold);
      background: rgba(214, 173, 96, 0.08);
      box-shadow: none;
    }

    /* Navbar */
    .navbar {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(7, 5, 6, 0.88);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid rgba(214, 173, 96, 0.15);
      transition: var(--transition);
    }
    .nav-container {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 84px;
      max-width: 1240px;
      margin: 0 auto;
      padding: 0 2rem;
    }
    .logo-container {
      display: flex;
      flex-direction: column;
    }
    .logo {
      font-family: var(--font-headline);
      font-size: 1.65rem;
      letter-spacing: 0.25em;
      color: var(--ivory);
      font-weight: 400;
      text-transform: uppercase;
      position: relative;
    }
    .logo span {
      color: var(--gold);
    }
    .logo-subtitle {
      font-size: 0.65rem;
      letter-spacing: 0.35em;
      text-transform: uppercase;
      color: var(--muted);
      margin-top: -2px;
    }
    .nav-links {
      display: flex;
      align-items: center;
      gap: 2.2rem;
      list-style: none;
    }
    .nav-links a {
      font-size: 0.88rem;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--muted);
      position: relative;
      padding: 0.4rem 0;
    }
    .nav-links a::after {
      content: "";
      position: absolute;
      bottom: 0;
      left: 50%;
      transform: translateX(-50%);
      width: 0;
      height: 1px;
      background: var(--gold);
      transition: var(--transition);
    }
    .nav-links a:hover,
    .nav-links a.active {
      color: var(--gold-soft);
    }
    .nav-links a.active::after,
    .nav-links a:hover::after {
      width: 100%;
    }

    .nav-cta {
      display: flex;
      align-items: center;
      gap: 1rem;
    }

    /* Mobile hamburger menu */
    .menu-toggle {
      display: none;
      flex-direction: column;
      gap: 6px;
      background: none;
      border: none;
      cursor: pointer;
      padding: 0.5rem;
      z-index: 101;
    }
    .menu-toggle span {
      display: block;
      width: 26px;
      height: 1.5px;
      background: var(--ivory);
      transition: var(--transition);
    }
    .menu-toggle.open span:nth-child(1) {
      transform: translateY(7.5px) rotate(45deg);
      background: var(--gold);
    }
    .menu-toggle.open span:nth-child(2) {
      opacity: 0;
    }
    .menu-toggle.open span:nth-child(3) {
      transform: translateY(-7.5px) rotate(-45deg);
      background: var(--gold);
    }

    /* HERO SECTION */
    .hero {
      position: relative;
      min-height: calc(100vh - 84px);
      display: flex;
      align-items: center;
      padding: 6rem 0 8rem;
      overflow: hidden;
    }
    .hero-bg {
      position: absolute;
      inset: 0;
      z-index: 0;
      background: url('https://source.unsplash.com/featured/2400x1400?museum,night') center/cover no-repeat;
      filter: brightness(0.38) saturate(1.2) contrast(1.15);
      transform: scale(1.04);
      transition: transform 12s ease-out;
    }
    .hero:hover .hero-bg {
      transform: scale(1.08);
    }
    .hero-overlay {
      position: absolute;
      inset: 0;
      z-index: 1;
      background: 
        radial-gradient(circle at 65% 35%, rgba(214, 173, 96, 0.12) 0%, transparent 60%),
        radial-gradient(circle at 20% 80%, rgba(58, 15, 29, 0.55) 0%, transparent 65%),
        linear-gradient(to bottom, rgba(7, 5, 6, 0.6) 0%, rgba(7, 5, 6, 0.4) 40%, #070506 100%),
        linear-gradient(to right, rgba(7, 5, 6, 0.95) 0%, rgba(7, 5, 6, 0.6) 50%, rgba(7, 5, 6, 0.85) 100%);
    }
    .hero-content {
      position: relative;
      z-index: 2;
      max-width: 860px;
    }
    .hero-badge-wrap {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      margin-bottom: 2rem;
    }
    .meta-badge {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      font-size: 0.75rem;
      letter-spacing: 0.15em;
      text-transform: uppercase;
      padding: 0.35rem 0.9rem;
      background: rgba(255, 244, 220, 0.05);
      border: 1px solid rgba(214, 173, 96, 0.3);
      border-radius: 100px;
      color: var(--gold-soft);
      backdrop-filter: blur(8px);
    }
    .meta-badge::before {
      content: "";
      width: 5px;
      height: 5px;
      background: var(--gold);
      border-radius: 50%;
      box-shadow: 0 0 8px var(--gold);
    }
    .hero-kicker {
      font-size: 0.9rem;
      text-transform: uppercase;
      letter-spacing: 0.35em;
      color: var(--gold);
      margin-bottom: 1rem;
      font-weight: 500;
    }
    .hero h1 {
      font-size: clamp(3.2rem, 7.5vw, 6.2rem);
      line-height: 1.02;
      margin-bottom: 1.5rem;
      font-weight: 300;
      color: var(--ivory);
      text-shadow: 0 4px 30px rgba(0,0,0,0.8);
    }
    .hero h1 em {
      font-style: italic;
      color: var(--gold-soft);
    }
    .hero-lead {
      font-size: clamp(1.1rem, 2vw, 1.4rem);
      color: var(--muted);
      line-height: 1.6;
      max-width: 680px;
      margin-bottom: 2.8rem;
    }
    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 1.25rem;
      align-items: center;
    }
    .hero-quick-meta {
      margin-top: 3.5rem;
      padding-top: 2rem;
      border-top: 1px solid rgba(214, 173, 96, 0.2);
      display: grid;
      grid-template-columns: repeat(3, auto);
      gap: 3rem;
      width: fit-content;
    }
    .quick-meta-item {
      display: flex;
      flex-direction: column;
    }
    .quick-meta-label {
      font-size: 0.72rem;
      text-transform: uppercase;
      letter-spacing: 0.2em;
      color: var(--gold);
      margin-bottom: 0.25rem;
    }
    .quick-meta-value {
      font-size: 1.05rem;
      color: var(--ivory);
      font-family: var(--font-headline);
    }

    /* SECTION BASICS */
    section {
      padding: 7rem 0;
      position: relative;
    }
    .section-header {
      margin-bottom: 4rem;
      max-width: 680px;
    }
    .section-eyebrow {
      font-size: 0.8rem;
      letter-spacing: 0.3em;
      text-transform: uppercase;
      color: var(--gold);
      margin-bottom: 0.8rem;
      display: block;
    }
    .section-title {
      font-size: clamp(2.4rem, 4.5vw, 3.8rem);
      line-height: 1.1;
      margin-bottom: 1.25rem;
      color: var(--ivory);
    }
    .section-desc {
      font-size: 1.15rem;
      color: var(--muted);
    }

    /* CONCEPT / INTRO */
    .concept-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 4rem;
      align-items: center;
      margin-bottom: 4rem;
    }
    .concept-editorial {
      font-family: var(--font-headline);
      font-size: clamp(1.4rem, 2.2vw, 1.9rem);
      line-height: 1.5;
      color: var(--ivory);
      position: relative;
      padding-left: 2rem;
      border-left: 2px solid var(--gold);
    }
    .concept-editorial span {
      color: var(--gold-soft);
    }
    .feature-cards {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 2rem;
    }
    .feature-card {
      background: var(--panel-bg);
      border: 1px solid var(--panel-border);
      padding: 2.8rem 2.2rem;
      position: relative;
      overflow: hidden;
      backdrop-filter: blur(12px);
      transition: var(--transition);
      border-radius: 2px;
    }
    .feature-card::before {
      content: "";
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 3px;
      background: linear-gradient(90deg, var(--gold), transparent);
      opacity: 0;
      transition: var(--transition);
    }
    .feature-card:hover {
      transform: translateY(-6px);
      border-color: var(--panel-border-bright);
      background: var(--panel-bg-hover);
      box-shadow: 0 16px 36px rgba(0, 0, 0, 0.45);
    }
    .feature-card:hover::before {
      opacity: 1;
    }
    .card-icon {
      width: 48px;
      height: 48px;
      margin-bottom: 1.8rem;
      color: var(--gold);
    }
    .feature-card h3 {
      font-size: 1.45rem;
      margin-bottom: 1rem;
      color: var(--ivory);
    }
    .feature-card p {
      font-size: 0.95rem;
      line-height: 1.65;
    }

    /* PROGRAM TIMELINE */
    .timeline-wrap {
      position: relative;
      max-width: 900px;
      margin: 0 auto;
    }
    .timeline-wrap::before {
      content: "";
      position: absolute;
      top: 0;
      bottom: 0;
      left: 120px;
      width: 1px;
      background: linear-gradient(180deg, transparent, var(--panel-border) 10%, var(--panel-border) 90%, transparent);
    }
    .timeline-item {
      display: flex;
      gap: 3.5rem;
      position: relative;
      margin-bottom: 3.5rem;
      align-items: flex-start;
    }
    .timeline-time {
      width: 120px;
      text-align: right;
      font-family: var(--font-headline);
      font-size: 1.4rem;
      color: var(--gold);
      padding-top: 0.2rem;
      flex-shrink: 0;
      letter-spacing: 0.05em;
    }
    .timeline-dot {
      position: absolute;
      left: 120px;
      top: 10px;
      transform: translateX(-50%);
      width: 11px;
      height: 11px;
      background: var(--bg-dark);
      border: 2px solid var(--gold);
      border-radius: 50%;
      box-shadow: 0 0 10px var(--gold-glow);
      z-index: 2;
      transition: var(--transition);
    }
    .timeline-item:hover .timeline-dot {
      background: var(--gold);
      transform: translateX(-50%) scale(1.3);
    }
    .timeline-body {
      background: var(--panel-bg);
      border: 1px solid var(--panel-border);
      padding: 1.8rem 2.2rem;
      flex-grow: 1;
      border-radius: 2px;
      backdrop-filter: blur(10px);
      transition: var(--transition);
    }
    .timeline-item:hover .timeline-body {
      border-color: var(--gold);
      transform: translateX(8px);
      background: var(--panel-bg-hover);
    }
    .timeline-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 0.6rem;
      flex-wrap: wrap;
      gap: 0.5rem;
    }
    .timeline-header h3 {
      font-size: 1.4rem;
      color: var(--ivory);
    }
    .location-tag {
      font-size: 0.72rem;
      text-transform: uppercase;
      letter-spacing: 0.15em;
      color: var(--gold-soft);
      border: 1px solid rgba(214, 173, 96, 0.25);
      padding: 0.25rem 0.65rem;
      border-radius: 3px;
      background: rgba(214, 173, 96, 0.05);
    }
    .timeline-desc {
      font-size: 0.98rem;
      color: var(--muted);
      line-height: 1.6;
    }

    /* ARTISTS / SPEAKERS */
    .artists-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 2rem;
    }
    .artist-card {
      background: var(--panel-bg);
      border: 1px solid var(--panel-border);
      border-radius: 2px;
      overflow: hidden;
      display: flex;
      flex-direction: column;
      transition: var(--transition);
      backdrop-filter: blur(8px);
    }
    .artist-card:hover {
      border-color: var(--panel-border-bright);
      transform: translateY(-8px);
      box-shadow: 0 14px 34px rgba(0, 0, 0, 0.5);
    }
    .artist-img-wrap {
      position: relative;
      height: 240px;
      overflow: hidden;
      background: #110d10;
    }
    .artist-img-wrap img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      filter: grayscale(35%) contrast(1.1);
      transition: transform 0.6s ease, filter 0.6s ease;
    }
    .artist-card:hover .artist-img-wrap img {
      transform: scale(1.08);
      filter: grayscale(0%) contrast(1.05);
    }
    .artist-img-wrap::after {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(180deg, transparent 40%, rgba(7, 5, 6, 0.85) 100%);
    }
    .artist-info {
      padding: 1.8rem 1.5rem;
      display: flex;
      flex-direction: column;
      flex-grow: 1;
    }
    .artist-role {
      font-size: 0.72rem;
      letter-spacing: 0.2em;
      text-transform: uppercase;
      color: var(--gold);
      margin-bottom: 0.4rem;
    }
    .artist-info h3 {
      font-size: 1.35rem;
      margin-bottom: 0.75rem;
      color: var(--ivory);
    }
    .artist-teaser {
      font-size: 0.9rem;
      color: var(--muted);
      line-height: 1.55;
      margin-bottom: 1.5rem;
      flex-grow: 1;
    }
    .artist-action-btn {
      width: 100%;
      padding: 0.65rem 1rem;
      font-size: 0.8rem;
      letter-spacing: 0.15em;
      border: 1px solid rgba(214, 173, 96, 0.35);
      background: rgba(214, 173, 96, 0.05);
      color: var(--gold-soft);
      cursor: pointer;
      text-transform: uppercase;
      transition: var(--transition);
      border-radius: 2px;
      outline: none;
    }
    .artist-action-btn:hover {
      background: var(--gold);
      color: #070506;
      border-color: var(--gold);
    }

    /* VENUE */
    .venue-grid {
      display: grid;
      grid-template-columns: 1.1fr 1fr;
      gap: 3.5rem;
      align-items: center;
    }
    .venue-details h3 {
      font-size: 2.4rem;
      margin-bottom: 0.5rem;
      color: var(--ivory);
    }
    .venue-address {
      font-size: 1.1rem;
      color: var(--gold-soft);
      margin-bottom: 2rem;
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }
    .venue-notes-list {
      display: flex;
      flex-direction: column;
      gap: 1.4rem;
      margin-bottom: 2rem;
    }
    .venue-note-item {
      background: var(--panel-bg);
      border-left: 2px solid var(--gold);
      padding: 1rem 1.4rem;
    }
    .venue-note-item h4 {
      font-size: 1.05rem;
      color: var(--ivory);
      margin-bottom: 0.25rem;
    }
    .venue-note-item p {
      font-size: 0.92rem;
      color: var(--muted);
      line-height: 1.5;
    }

    /* SVG MAP MOCK */
    .map-container {
      background: #090a0f;
      border: 1px solid var(--panel-border);
      border-radius: 4px;
      padding: 1.5rem;
      position: relative;
      box-shadow: 0 18px 45px rgba(0,0,0,0.6);
    }
    .map-svg-wrap {
      width: 100%;
      height: 380px;
      border-radius: 2px;
      overflow: hidden;
      background: #07080c;
    }
    .map-svg {
      width: 100%;
      height: 100%;
      display: block;
    }

    /* TICKET TIERS */
    .tickets-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 2rem;
      align-items: stretch;
    }
    .ticket-card {
      background: var(--panel-bg);
      border: 1px solid var(--panel-border);
      border-radius: 3px;
      padding: 3rem 2.2rem 2.5rem;
      display: flex;
      flex-direction: column;
      position: relative;
      transition: var(--transition);
      backdrop-filter: blur(12px);
    }
    .ticket-card:hover {
      transform: translateY(-10px);
      border-color: var(--gold-soft);
      box-shadow: 0 20px 45px rgba(0, 0, 0, 0.6);
    }
    .ticket-card.recommended {
      background: linear-gradient(180deg, rgba(58, 15, 29, 0.25) 0%, rgba(7, 5, 6, 0.4) 100%);
      border: 1.5px solid var(--gold);
      box-shadow: 0 10px 30px rgba(214, 173, 96, 0.15);
    }
    .recommended-badge {
      position: absolute;
      top: -13px;
      left: 50%;
      transform: translateX(-50%);
      background: var(--gold);
      color: #070506;
      font-size: 0.68rem;
      font-weight: 700;
      letter-spacing: 0.2em;
      text-transform: uppercase;
      padding: 0.35rem 1rem;
      border-radius: 100px;
      box-shadow: 0 4px 12px rgba(214, 173, 96, 0.4);
    }
    .ticket-tier-name {
      font-size: 1.7rem;
      color: var(--ivory);
      margin-bottom: 0.5rem;
      text-align: center;
    }
    .ticket-price-wrap {
      text-align: center;
      margin: 1.5rem 0 2rem;
      padding-bottom: 1.8rem;
      border-bottom: 1px solid rgba(214, 173, 96, 0.2);
    }
    .ticket-price {
      font-family: var(--font-headline);
      font-size: 3.5rem;
      color: var(--gold-soft);
      line-height: 1;
    }
    .ticket-price-sub {
      font-size: 0.8rem;
      color: var(--muted);
      letter-spacing: 0.1em;
      text-transform: uppercase;
      margin-top: 0.4rem;
    }
    .ticket-features {
      list-style: none;
      margin-bottom: 2.5rem;
      flex-grow: 1;
      display: flex;
      flex-direction: column;
      gap: 1rem;
    }
    .ticket-features li {
      font-size: 0.94rem;
      color: var(--ivory);
      display: flex;
      align-items: center;
      gap: 0.75rem;
    }
    .ticket-features li::before {
      content: "✦";
      color: var(--gold);
      font-size: 0.8rem;
      flex-shrink: 0;
    }

    /* FAQ ACCORDION */
    .faq-container {
      max-width: 860px;
      margin: 0 auto;
    }
    .faq-item {
      border-bottom: 1px solid rgba(214, 173, 96, 0.22);
      transition: var(--transition);
    }
    .faq-item:first-child {
      border-top: 1px solid rgba(214, 173, 96, 0.22);
    }
    .faq-trigger {
      width: 100%;
      text-align: left;
      padding: 1.8rem 0;
      background: none;
      border: none;
      color: var(--ivory);
      font-family: var(--font-headline);
      font-size: 1.3rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
      cursor: pointer;
      outline: none;
      transition: var(--transition);
    }
    .faq-trigger:hover {
      color: var(--gold-soft);
    }
    .faq-icon {
      font-size: 1.4rem;
      color: var(--gold);
      transition: transform 0.35s ease;
      font-weight: 300;
    }
    .faq-item.active .faq-icon {
      transform: rotate(45deg);
    }
    .faq-content {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.4s cubic-bezier(0.25, 1, 0.5, 1), opacity 0.35s ease;
      opacity: 0;
    }
    .faq-item.active .faq-content {
      max-height: 250px;
      opacity: 1;
    }
    .faq-inner {
      padding-bottom: 1.8rem;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.7;
    }

    /* NEWSLETTER */
    .newsletter-section {
      background: linear-gradient(180deg, transparent, rgba(58, 15, 29, 0.2) 50%, transparent);
      text-align: center;
      padding: 6rem 0;
    }
    .newsletter-box {
      max-width: 640px;
      margin: 0 auto;
      background: var(--panel-bg);
      border: 1px solid var(--panel-border);
      padding: 3.5rem 2.5rem;
      border-radius: 2px;
      backdrop-filter: blur(14px);
    }
    .newsletter-box h3 {
      font-size: 2.2rem;
      margin-bottom: 0.8rem;
      color: var(--ivory);
    }
    .newsletter-box p {
      font-size: 1rem;
      color: var(--muted);
      margin-bottom: 2rem;
    }
    .newsletter-form {
      display: flex;
      gap: 0.75rem;
      max-width: 480px;
      margin: 0 auto;
      position: relative;
    }
    .newsletter-input {
      flex: 1;
      padding: 0.9rem 1.25rem;
      background: rgba(7, 5, 6, 0.8);
      border: 1px solid var(--panel-border);
      color: var(--ivory);
      font-family: var(--font-body);
      font-size: 0.95rem;
      border-radius: 2px;
      outline: none;
      transition: var(--transition);
    }
    .newsletter-input:focus {
      border-color: var(--gold);
      box-shadow: 0 0 15px rgba(214, 173, 96, 0.25);
    }
    .form-error-msg {
      position: absolute;
      bottom: -1.75rem;
      left: 0;
      font-size: 0.75rem;
      color: #ff6b6b;
      display: none;
    }

    /* FOOTER */
    footer {
      background: #040304;
      border-top: 1px solid rgba(214, 173, 96, 0.15);
      padding: 5rem 0 3rem;
      font-size: 0.9rem;
    }
    .footer-grid {
      display: grid;
      grid-template-columns: 2fr 1fr 1fr;
      gap: 3.5rem;
      margin-bottom: 4rem;
    }
    .footer-brand .logo {
      margin-bottom: 1rem;
      display: inline-block;
    }
    .footer-brand p {
      max-width: 380px;
      font-size: 0.92rem;
      color: var(--muted);
      line-height: 1.6;
    }
    .footer-col h5 {
      font-family: var(--font-headline);
      font-size: 1.1rem;
      color: var(--ivory);
      margin-bottom: 1.2rem;
      letter-spacing: 0.05em;
    }
    .footer-links {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 0.65rem;
    }
    .footer-links a {
      color: var(--muted);
      font-size: 0.88rem;
    }
    .footer-links a:hover {
      color: var(--gold-soft);
      padding-left: 4px;
    }
    .footer-bottom {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding-top: 2rem;
      border-top: 1px solid rgba(255, 255, 255, 0.06);
      flex-wrap: wrap;
      gap: 1rem;
    }
    .footer-disclaimer {
      font-size: 0.8rem;
      color: var(--gold);
      opacity: 0.85;
      letter-spacing: 0.04em;
    }
    .footer-copy {
      font-size: 0.8rem;
      color: var(--muted);
    }

    /* MODALS */
    .modal-backdrop {
      position: fixed;
      inset: 0;
      background: rgba(7, 5, 6, 0.85);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      z-index: 1000;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 1.5rem;
      opacity: 0;
      visibility: hidden;
      transition: opacity 0.35s ease, visibility 0.35s ease;
    }
    .modal-backdrop.open {
      opacity: 1;
      visibility: visible;
    }
    .modal-box {
      background: #0f0a0d;
      border: 1px solid var(--panel-border-bright);
      width: 100%;
      max-width: 620px;
      max-height: 90vh;
      overflow-y: auto;
      border-radius: 4px;
      position: relative;
      box-shadow: 0 25px 60px rgba(0, 0, 0, 0.8), 0 0 40px rgba(214, 173, 96, 0.15);
      transform: translateY(20px) scale(0.97);
      transition: transform 0.35s cubic-bezier(0.25, 1, 0.5, 1);
    }
    .modal-backdrop.open .modal-box {
      transform: translateY(0) scale(1);
    }
    .modal-close-btn {
      position: absolute;
      top: 1.25rem;
      right: 1.25rem;
      background: rgba(255, 255, 255, 0.05);
      border: 1px solid rgba(214, 173, 96, 0.3);
      color: var(--ivory);
      width: 36px;
      height: 36px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.3rem;
      cursor: pointer;
      transition: var(--transition);
      z-index: 10;
      outline: none;
    }
    .modal-close-btn:hover {
      background: var(--gold);
      color: #070506;
      border-color: var(--gold);
    }

    /* Artist Modal Interior */
    .artist-modal-content {
      display: flex;
      flex-direction: column;
    }
    .artist-modal-img {
      width: 100%;
      height: 280px;
      object-fit: cover;
      border-bottom: 1px solid var(--panel-border);
    }
    .artist-modal-body {
      padding: 2.2rem;
    }
    .artist-modal-role {
      font-size: 0.75rem;
      text-transform: uppercase;
      letter-spacing: 0.2em;
      color: var(--gold);
      margin-bottom: 0.4rem;
    }
    .artist-modal-body h3 {
      font-size: 2rem;
      margin-bottom: 0.6rem;
      color: var(--ivory);
    }
    .artist-modal-session {
      display: inline-block;
      font-size: 0.85rem;
      color: var(--gold-soft);
      background: rgba(214, 173, 96, 0.08);
      border: 1px solid rgba(214, 173, 96, 0.25);
      padding: 0.3rem 0.8rem;
      border-radius: 2px;
      margin-bottom: 1.4rem;
    }
    .artist-modal-bio {
      font-size: 1rem;
      line-height: 1.7;
      color: var(--muted);
    }

    /* Ticket Checkout Modal Interior */
    .ticket-modal-body {
      padding: 2.5rem;
    }
    .ticket-modal-body h3 {
      font-size: 1.9rem;
      margin-bottom: 0.4rem;
    }
    .modal-sub {
      font-size: 0.95rem;
      color: var(--muted);
      margin-bottom: 1.8rem;
    }
    .form-group {
      margin-bottom: 1.4rem;
    }
    .form-group label {
      display: block;
      font-size: 0.82rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--gold-soft);
      margin-bottom: 0.45rem;
    }
    .form-group input, 
    .form-group select {
      width: 100%;
      padding: 0.85rem 1rem;
      background: rgba(7, 5, 6, 0.75);
      border: 1px solid var(--panel-border);
      color: var(--ivory);
      font-family: var(--font-body);
      font-size: 0.95rem;
      border-radius: 2px;
      outline: none;
      transition: var(--transition);
    }
    .form-group input:focus,
    .form-group select:focus {
      border-color: var(--gold);
      box-shadow: 0 0 12px rgba(214, 173, 96, 0.25);
    }
    .form-row {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1rem;
    }
    .modal-price-calc {
      background: rgba(255, 244, 220, 0.03);
      border: 1px dashed var(--panel-border);
      padding: 1.2rem;
      border-radius: 2px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 1.5rem;
    }
    .calc-total-label {
      font-size: 0.9rem;
      color: var(--muted);
    }
    .calc-total-val {
      font-family: var(--font-headline);
      font-size: 1.8rem;
      color: var(--gold-soft);
    }
    .terms-wrap {
      display: flex;
      align-items: flex-start;
      gap: 0.65rem;
      margin-bottom: 1.8rem;
    }
    .terms-wrap input {
      margin-top: 0.25rem;
      accent-color: var(--gold);
      cursor: pointer;
    }
    .terms-wrap label {
      font-size: 0.85rem;
      color: var(--muted);
      line-height: 1.45;
      cursor: pointer;
    }
    .ticket-validation-error {
      color: #ff6b6b;
      font-size: 0.82rem;
      margin-bottom: 1rem;
      display: none;
    }

    /* TOAST NOTIFICATION */
    .toast-container {
      position: fixed;
      bottom: 2rem;
      right: 2rem;
      z-index: 2000;
      display: flex;
      flex-direction: column;
      gap: 0.75rem;
      pointer-events: none;
    }
    .toast {
      pointer-events: auto;
      background: #140d12;
      border: 1px solid var(--gold);
      color: var(--ivory);
      padding: 1rem 1.6rem;
      border-radius: 3px;
      box-shadow: 0 10px 30px rgba(0, 0, 0, 0.6), 0 0 20px rgba(214, 173, 96, 0.2);
      font-size: 0.92rem;
      display: flex;
      align-items: center;
      gap: 0.85rem;
      transform: translateX(120%);
      transition: transform 0.4s cubic-bezier(0.25, 1, 0.5, 1);
    }
    .toast.show {
      transform: translateX(0);
    }
    .toast-icon {
      color: var(--gold);
      font-size: 1.2rem;
      flex-shrink: 0;
    }

    /* SCROLL REVEAL ANIMATIONS */
    .reveal {
      opacity: 0;
      transform: translateY(30px);
      transition: opacity 0.8s cubic-bezier(0.25, 1, 0.5, 1), transform 0.8s cubic-bezier(0.25, 1, 0.5, 1);
    }
    .reveal.active {
      opacity: 1;
      transform: translateY(0);
    }

    /* RESPONSIVE DESIGN */
    @media (max-width: 1024px) {
      .artists-grid {
        grid-template-columns: repeat(2, 1fr);
      }
      .tickets-grid {
        grid-template-columns: repeat(3, 1fr);
      }
      .footer-grid {
        grid-template-columns: 1fr 1fr;
      }
    }

    @media (max-width: 860px) {
      .concept-grid {
        grid-template-columns: 1fr;
        gap: 2rem;
      }
      .feature-cards {
        grid-template-columns: 1fr;
      }
      .venue-grid {
        grid-template-columns: 1fr;
      }
      .tickets-grid {
        grid-template-columns: 1fr;
        max-width: 480px;
        margin: 0 auto;
      }
      .hero-quick-meta {
        grid-template-columns: 1fr;
        gap: 1.25rem;
      }
      .menu-toggle {
        display: flex;
      }
      .nav-links {
        position: fixed;
        top: 84px;
        left: 0;
        right: 0;
        background: rgba(7, 5, 6, 0.98);
        border-bottom: 1px solid var(--panel-border);
        flex-direction: column;
        padding: 2.5rem;
        gap: 1.8rem;
        transform: translateY(-150%);
        transition: transform 0.4s ease;
        box-shadow: 0 20px 40px rgba(0,0,0,0.8);
      }
      .nav-links.open {
        transform: translateY(0);
      }
      .timeline-wrap::before {
        left: 20px;
      }
      .timeline-item {
        flex-direction: column;
        gap: 0.8rem;
        padding-left: 45px;
      }
      .timeline-time {
        text-align: left;
        width: auto;
      }
      .timeline-dot {
        left: 20px;
        top: 6px;
      }
      .footer-grid {
        grid-template-columns: 1fr;
      }
      .form-row {
        grid-template-columns: 1fr;
      }
    }

    @media (max-width: 520px) {
      .artists-grid {
        grid-template-columns: 1fr;
      }
      .newsletter-form {
        flex-direction: column;
      }
      .hero-actions {
        flex-direction: column;
        align-items: stretch;
      }
      .hero-actions .btn {
        width: 100%;
      }
      .nav-cta {
        display: none;
      }
    }
  </style>
</head>
<body>

  <!-- Ambient background glow blooms -->
  <div class="ambient-bloom bloom-1"></div>
  <div class="ambient-bloom bloom-2"></div>
  <div class="ambient-bloom bloom-3"></div>

  <!-- 1. NAVBAR -->
  <header class="navbar" id="navbar">
    <div class="nav-container">
      <a href="#" class="logo-container" aria-label="ARTIFACT Home">
        <div class="logo">ARTIFACT<span>.</span></div>
        <div class="logo-subtitle">MUSEUM NIGHT</div>
      </a>

      <button class="menu-toggle" id="menuToggle" aria-label="Toggle navigation menu" aria-expanded="false">
        <span></span>
        <span></span>
        <span></span>
      </button>

      <ul class="nav-links" id="navLinks">
        <li><a href="#program">Program</a></li>
        <li><a href="#artists">Artists</a></li>
        <li><a href="#venue">Venue</a></li>
        <li><a href="#tickets">Tickets</a></li>
        <li><a href="#faq">FAQ</a></li>
      </ul>

      <div class="nav-cta">
        <a href="#tickets" class="btn btn-solid" style="padding: 0.65rem 1.4rem; font-size: 0.85rem;">Get Tickets</a>
      </div>
    </div>
  </header>

  <main>
    <!-- 2. HERO -->
    <section class="hero" id="home">
      <div class="hero-bg"></div>
      <div class="hero-overlay"></div>
      <div class="container hero-content">
        <div class="hero-badge-wrap">
          <span class="meta-badge">18 October 2026</span>
          <span class="meta-badge">19:00 — 02:00</span>
          <span class="meta-badge">The Old Gallery, Warsaw</span>
        </div>

        <div class="hero-kicker">ARTIFACT: Museum Night</div>
        <h1>Museum Night,<br><em>Reimagined.</em></h1>
        <p class="hero-lead">
          Step into velvet darkness and quiet mystery. An exclusive after-hours journey uniting rare archival collections, live ambient soundscapes, golden spotlights, and art-house cinema under the arches of The Old Gallery.
        </p>

        <div class="hero-actions">
          <a href="#tickets" class="btn btn-solid">Get Tickets</a>
          <button class="btn btn-ghost" id="saveCalendarHeroBtn">Save to Calendar</button>
        </div>

        <div class="hero-quick-meta">
          <div class="quick-meta-item">
            <span class="quick-meta-label">Date</span>
            <span class="quick-meta-value">18 Oct 2026</span>
          </div>
          <div class="quick-meta-item">
            <span class="quick-meta-label">Hours</span>
            <span class="quick-meta-value">19:00 – 02:00</span>
          </div>
          <div class="quick-meta-item">
            <span class="quick-meta-label">Location</span>
            <span class="quick-meta-value">Warsaw, PL</span>
          </div>
        </div>
      </div>
    </section>

    <!-- 3. CONCEPT / INTRO -->
    <section id="concept">
      <div class="container">
        <div class="concept-grid reveal">
          <div class="section-header" style="margin-bottom: 0;">
            <span class="section-eyebrow">The Nocturnal Salon</span>
            <h2 class="section-title">Where History Meets Velvet Darkness</h2>
          </div>
          <div class="concept-editorial">
            “Once the grand gates lock to the general public, ARTIFACT transforms the museum into a luminous sanctuary of <span>curatorial intimacy and sonic reverie</span>.”
          </div>
        </div>

        <div class="feature-cards">
          <div class="feature-card reveal">
            <svg class="card-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">
              <path d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" />
            </svg>
            <h3>After-Hours Exhibitions</h3>
            <p>Experience world-renowned masterpieces unburdened by daytime crowds. Walk illuminated halls with bespoke low-lux spotlighting engineered for profound focus.</p>
          </div>

          <div class="feature-card reveal">
            <svg class="card-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">
              <path d="M9 19V6l12-3v13M9 19c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zm12-3c0 1.105-1.343 2-3 2s-3-.895-3-2 1.343-2 3-2 3 .895 3 2zM9 10l12-3" />
            </svg>
            <h3>Live Performances</h3>
            <p>Atmospheric electro-acoustic sets and experimental modular synthesizers dialogue with neoclassical marble sculptures throughout the courtyards.</p>
          </div>

          <div class="feature-card reveal">
            <svg class="card-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">
              <path d="M15 7a2 2 0 012 2m4 0a6 6 0 01-7.743 5.743L11 17H9v2H7v2H4a1 1 0 01-1-1v-2.586a1 1 0 01.293-.707l5.964-5.964A6 6 0 1121 9z" />
            </svg>
            <h3>Guided Hidden-Room Tours</h3>
            <p>Access restricted subterranean storage vaults, private restoration studios, and archival drawers guarded for over a century, led by head curators.</p>
          </div>
        </div>
      </div>
    </section>

    <div class="container"><div class="gold-divider"></div></div>

    <!-- 4. PROGRAM TIMELINE -->
    <section id="program">
      <div class="container">
        <div class="section-header reveal">
          <span class="section-eyebrow">Curated Schedule</span>
          <h2 class="section-title">Hour-by-Hour Timeline</h2>
          <p class="section-desc">A carefully orchestrated nocturnal choreography of light, discourse, and spatial acoustic immersion.</p>
        </div>

        <div class="timeline-wrap">
          <!-- 19:00 -->
          <div class="timeline-item reveal">
            <div class="timeline-time">19:00</div>
            <div class="timeline-dot"></div>
            <div class="timeline-body">
              <div class="timeline-header">
                <h3>Doors Open</h3>
                <span class="location-tag">Main Vestibule</span>
              </div>
              <p class="timeline-desc">Arrival drinks, cloakroom reception, and first twilight walkthrough of the central cloister under warm ambient illumination.</p>
            </div>
          </div>

          <!-- 19:30 -->
          <div class="timeline-item reveal">
            <div class="timeline-time">19:30</div>
            <div class="timeline-dot"></div>
            <div class="timeline-body">
              <div class="timeline-header">
                <h3>Curator Welcome</h3>
                <span class="location-tag">Grand Rotunda</span>
              </div>
              <p class="timeline-desc">Opening address by Chief Curator Dr. Elżbieta Wójcik detailing the restoration journeys of newly unveiled Renaissance artifacts.</p>
            </div>
          </div>

          <!-- 20:00 -->
          <div class="timeline-item reveal">
            <div class="timeline-time">20:00</div>
            <div class="timeline-dot"></div>
            <div class="timeline-body">
              <div class="timeline-header">
                <h3>Hidden Collection Tour</h3>
                <span class="location-tag">Subterranean Vaults</span>
              </div>
              <p class="timeline-desc">Guided descent into underground archival chambers containing non-catalogued fragments, illuminated only by handheld brass torches.</p>
            </div>
          </div>

          <!-- 21:00 -->
          <div class="timeline-item reveal">
            <div class="timeline-time">21:00</div>
            <div class="timeline-dot"></div>
            <div class="timeline-body">
              <div class="timeline-header">
                <h3>Live Ambient Performance</h3>
                <span class="location-tag">Sculpture Courtyard</span>
              </div>
              <p class="timeline-desc">Cellist and electronic sound sculptor Julian Vance performs an original four-channel score resonating against cold marble surfaces.</p>
            </div>
          </div>

          <!-- 22:00 -->
          <div class="timeline-item reveal">
            <div class="timeline-time">22:00</div>
            <div class="timeline-dot"></div>
            <div class="timeline-body">
              <div class="timeline-header">
                <h3>Sculpture Hall Projection</h3>
