      // 2. TOAST NOTIFICATION UTILITY
      const toastContainer = document.getElementById('toastContainer');
      function showToast(message, icon = "✦") {
        const toast = document.createElement('div');
        toast.className = 'toast';
        toast.innerHTML = `<span class="toast-icon">${icon}</span><span>${message}</span>`;
        toastContainer.appendChild(toast);

        // Force reflow
        void toast.offsetWidth;
        toast.classList.add('show');

        setTimeout(() => {
          toast.classList.remove('show');
          setTimeout(() => {
            if (toast.parentNode) {
              toast.parentNode.removeChild(toast);
            }
          }, 400);
        }, 4000);
      }

      // 3. SAVE TO CALENDAR (.ICS FILE GENERATION)
      function downloadICS() {
        const icsData = [
          "BEGIN:VCALENDAR",
          "VERSION:2.0",
          "PRODID:-//ARTIFACT//Museum Night 2026//EN",
          "CALSCALE:GREGORIAN",
          "METHOD:PUBLISH",
          "BEGIN:VEVENT",
          "UID:artifact-museum-night-2026@artifact-night.org",
          "DTSTAMP:20260101T000000Z",
          "DTSTART:20261018T190000",
          "DTEND:20261019T020000",
          "SUMMARY:ARTIFACT: Museum Night",
          "LOCATION:The Old Gallery\\, Warsaw",
          "DESCRIPTION:A cinematic after-hours museum event with exhibitions\\, performances\\, talks\\, and guided tours.",
          "STATUS:CONFIRMED",
          "END:VEVENT",
          "END:VCALENDAR"
        ].join("\\r\\n");

        const blob = new Blob([icsData], { type: 'text/calendar;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.setAttribute('download', 'artifact-museum-night.ics');
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);

        showToast("Calendar invitation 'artifact-museum-night.ics' downloaded.");
      }

      const saveHeroBtn = document.getElementById('saveCalendarHeroBtn');
      if (saveHeroBtn) saveHeroBtn.addEventListener('click', downloadICS);

      const saveFooterBtn = document.getElementById('saveCalendarFooterBtn');
      if (saveFooterBtn) saveFooterBtn.addEventListener('click', downloadICS);

      // 4. MOBILE NAVIGATION
      const menuToggle = document.getElementById('menuToggle');
      const navLinks = document.getElementById('navLinks');

      menuToggle.addEventListener('click', () => {
        const isOpen = navLinks.classList.toggle('open');
        menuToggle.classList.toggle('open');
        menuToggle.setAttribute('aria-expanded', isOpen);
      });

      document.querySelectorAll('.nav-links a').forEach(link => {
        link.addEventListener('click', () => {
          navLinks.classList.remove('open');
          menuToggle.classList.remove('open');
          menuToggle.setAttribute('aria-expanded', 'false');
        });
      });

      // 5. ACTIVE NAV STATE ON SCROLL
      const sections = document.querySelectorAll('section[id]');
      const navItems = document.querySelectorAll('.nav-links a');

      function updateActiveNav() {
        const scrollY = window.pageYOffset + 120;
        sections.forEach(current => {
          const sectionHeight = current.offsetHeight;
          const sectionTop = current.offsetTop;
          const sectionId = current.getAttribute('id');

          if (scrollY >= sectionTop && scrollY < sectionTop + sectionHeight) {
            navItems.forEach(item => {
              item.classList.remove('active');
              if (item.getAttribute('href') === `#${sectionId}`) {
                item.classList.add('active');
              }
            });
          }
        });
      }
      window.addEventListener('scroll', updateActiveNav);

      // 6. SCROLL REVEAL ANIMATIONS
      const revealElements = document.querySelectorAll('.reveal');
      const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.add('active');
          }
        });
      }, {
        threshold: 0.15,
        rootMargin: '0px 0px -40px 0px'
      });

      revealElements.forEach(el => observer.observe(el));

      // 7. FAQ ACCORDION
      const faqItems = document.querySelectorAll('.faq-item');
      faqItems.forEach(item => {
        const trigger = item.querySelector('.faq-trigger');
        trigger.addEventListener('click', () => {
          const isActive = item.classList.contains('active');
          faqItems.forEach(otherItem => {
            otherItem.classList.remove('active');
            otherItem.querySelector('.faq-trigger').setAttribute('aria-expanded', 'false');
          });

          if (!isActive) {
            item.classList.add('active');
            trigger.setAttribute('aria-expanded', 'true');
          }
        });
      });

      // 8. ARTIST MODAL
      const artistModal = document.getElementById('artistModal');
      const closeArtistModal = document.getElementById('closeArtistModal');
      const modalArtistImg = document.getElementById('modalArtistImg');
      const modalArtistRole = document.getElementById('modalArtistRole');
      const modalArtistName = document.getElementById('modalArtistName');
      const modalArtistSession = document.getElementById('modalArtistSession');
      const modalArtistBio = document.getElementById('modalArtistBio');

      function openArtist(index) {
        const data = artistsData[index];
        if (!data) return;

        modalArtistImg.src = data.image;
        modalArtistImg.alt = data.name;
        modalArtistRole.textContent = data.role;
        modalArtistName.textContent = data.name;
        modalArtistSession.textContent = data.session;
        modalArtistBio.textContent = data.bio;

        artistModal.classList.add('open');
        artistModal.setAttribute('aria-hidden', 'false');
        document.body.style.overflow = 'hidden';
      }

      function hideArtistModal() {
        artistModal.classList.remove('open');
        artistModal.setAttribute('aria-hidden', 'true');
        document.body.style.overflow = '';
      }

      document.querySelectorAll('.artist-action-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          const idx = parseInt(btn.getAttribute('data-artist'), 10);
          openArtist(idx);
        });
      });

      closeArtistModal.addEventListener('click', hideArtistModal);
      artistModal.addEventListener('click', (e) => {
        if (e.target === artistModal) hideArtistModal();
      });

      // 9. TICKET MODAL CHECKOUT MOCK
      const ticketModal = document.getElementById('ticketModal');
      const closeTicketModal = document.getElementById('closeTicketModal');
      const checkoutTierTitle = document.getElementById('checkoutTierTitle');
      const selectedTierSelect = document.getElementById('selectedTierSelect');
      const ticketCount = document.getElementById('ticketCount');
      const checkoutTotalPrice = document.getElementById('checkoutTotalPrice');
      const checkoutForm = document.getElementById('checkoutForm');
      const checkoutError = document.getElementById('checkoutError');

      const prices = {
        'Night Pass': 29,
        'Curator Pass': 59,
        'Patron Pass': 129
      };

      function updateCheckoutPrice() {
        const tier = selectedTierSelect.value;
        const count = parseInt(ticketCount.value, 10);
        const pricePer = prices[tier] || 59;
        const total = pricePer * count;
        checkoutTotalPrice.textContent = `€${total}`;
        checkoutTierTitle.textContent = tier;
      }

      function openTicketModal(tierName) {
        if (tierName && prices[tierName]) {
          selectedTierSelect.value = tierName;
        }
        updateCheckoutPrice();
        ticketModal.classList.add('open');
        ticketModal.setAttribute('aria-hidden', 'false');
        document.body.style.overflow = 'hidden';
      }

      function hideTicketModal() {
        ticketModal.classList.remove('open');
        ticketModal.setAttribute('aria-hidden', 'true');
        checkoutError.style.display = 'none';
        document.body.style.overflow = '';
      }

      document.querySelectorAll('.select-tier-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          const tier = btn.getAttribute('data-tier');
          openTicketModal(tier);
        });
      });

      selectedTierSelect.addEventListener('change', updateCheckoutPrice);
      ticketCount.addEventListener('change', updateCheckoutPrice);

      closeTicketModal.addEventListener('click', hideTicketModal);
      ticketModal.addEventListener('click', (e) => {
        if (e.target === ticketModal) hideTicketModal();
      });

      // Form validation & submission mock
      checkoutForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const name = document.getElementById('attendeeName').value.trim();
        const email = document.getElementById('attendeeEmail').value.trim();
        const terms = document.getElementById('termsCheck').checked;
        const emailPattern = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;

        if (!name || !email || !emailPattern.test(email) || !terms) {
          checkoutError.style.display = 'block';
          return;
        }

        checkoutError.style.display = 'none';
        const tier = selectedTierSelect.value;
        const count = ticketCount.value;

        hideTicketModal();
        showToast(`Reservation Confirmed: ${count} × ${tier} reserved for ${name}.`);
        checkoutForm.reset();
        selectedTierSelect.value = 'Curator Pass';
        updateCheckoutPrice();
      });

      // 10. GLOBAL ESCAPE KEY MODAL DISMISSAL
      window.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
          if (artistModal.classList.contains('open')) hideArtistModal();
          if (ticketModal.classList.contains('open')) hideTicketModal();
        }
      });

      // 11. NEWSLETTER VALIDATION
      const newsletterForm = document.getElementById('newsletterForm');
      const newsletterEmail = document.getElementById('newsletterEmail');
      const newsletterError = document.getElementById('newsletterError');

      newsletterForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const email = newsletterEmail.value.trim();
        const emailPattern = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;

        if (!email || !emailPattern.test(email)) {
          newsletterError.style.display = 'block';
          newsletterEmail.focus();
          return;
        }

        newsletterError.style.display = 'none';
        newsletterEmail.value = '';
        showToast("Subscribed: Welcome to the private nocturnal dispatches.");
      });
    });
  </script>
</body>
</html>
